head.script:
window.adobeDataLayer = window.adobeDataLayer || [];
window.growthbook_config = window.growthbook_config || { };

window.growthbook_config.trackingCallback = function (experiment, result) {
    window.adobeDataLayer.push({
        event: "growthbook.experiment_viewed",
        growthbook: {
            experimentId: experiment.key,
            variationId: result.key
        }
    });
};

window.growthbook_queue = window.growthbook_queue || [];
window.growthbook_queue.push(function () {
    var s = document.getElementById("gb-af"); if (s) s.remove();
});
setTimeout(function () {
    var s = document.getElementById("gb-af"); if (s) s.remove();
}, 2000);

body.script:
var dataLayerName = 'adobeDataLayer' || 'adobeDataLayer';
window[dataLayerName] = window[dataLayerName] || [];
// Custom to remove cmp:show events from dataLayer, it is replaced by pageViewed event in analytics/core.js

